    ///<summary>
    ///Represents information about a customer of the shop, such as the customer's contact details, their order
    ///history, and whether they've agreed to receive marketing material by email.
    ///
    ///**Caution:** Only use this data if it's required for your app's functionality. Shopify will restrict [access to scopes](https://shopify.dev/api/usage/access-scopes) for apps that don't have a legitimate use for the associated data.
    ///</summary>
    public class Customer : GraphQLObject<Customer>, ICommentEventSubject, IHasEvents, IHasMetafieldDefinitions, IHasMetafields, IHasStoreCreditAccounts, ILegacyInteroperability, INode, ICommentEventEmbed, IMetafieldReference, IMetafieldReferencer, IPurchasingEntity
    {
        ///<summary>
        ///A list of addresses associated with the customer.
        ///</summary>
        [NonNull]
        public IEnumerable<MailingAddress>? addresses { get; set; }

        ///<summary>
        ///The addresses associated with the customer.
        ///</summary>
        [NonNull]
        public MailingAddressConnection? addressesV2 { get; set; }

        ///<summary>
        ///The total amount that the customer has spent on orders in their lifetime.
        ///</summary>
        [NonNull]
        public MoneyV2? amountSpent { get; set; }

        ///<summary>
        ///Whether the merchant can delete the customer from their store.
        ///
        ///A customer can be deleted from a store only if they haven't yet made an order. After a customer makes an
        ///order, they can't be deleted from a store.
        ///</summary>
        [NonNull]
        public bool? canDelete { get; set; }

        ///<summary>
        ///A list of the customer's company contact profiles.
        ///</summary>
        [NonNull]
        public IEnumerable<CompanyContact>? companyContactProfiles { get; set; }

        ///<summary>
        ///The date and time when the customer was added to the store.
        ///</summary>
        [NonNull]
        public DateTime? createdAt { get; set; }

        ///<summary>
        ///Whether the customer has opted out of having their data sold.
        ///</summary>
        [NonNull]
        public bool? dataSaleOptOut { get; set; }
        ///<summary>
        ///The default address associated with the customer.
        ///</summary>
        public MailingAddress? defaultAddress { get; set; }
        ///<summary>
        ///The customer's default email address.
        ///</summary>
        public CustomerEmailAddress? defaultEmailAddress { get; set; }
        ///<summary>
        ///The customer's default phone number.
        ///</summary>
        public CustomerPhoneNumber? defaultPhoneNumber { get; set; }

        ///<summary>
        ///The full name of the customer, based on the values for first_name and last_name. If the first_name and
        ///last_name are not available, then this falls back to the customer's email address, and if that is not available, the customer's phone number.
        ///</summary>
        [NonNull]
        public string? displayName { get; set; }

        ///<summary>
        ///The customer's email address.
        ///</summary>
        [Obsolete("Use `defaultEmailAddress.emailAddress` instead.")]
        public string? email { get; set; }

        ///<summary>
        ///The current email marketing state for the customer.
        ///If the customer doesn't have an email address, then this property is `null`.
        ///</summary>
        [Obsolete("Use `defaultEmailAddress.marketingState`, `defaultEmailAddress.marketingOptInLevel`, `defaultEmailAddress.marketingUpdatedAt`, and `defaultEmailAddress.sourceLocation` instead.")]
        public CustomerEmailMarketingConsentState? emailMarketingConsent { get; set; }

        ///<summary>
        ///A list of events associated with the customer.
        ///</summary>
        [NonNull]
        public EventConnection? events { get; set; }
        ///<summary>
        ///The customer's first name.
        ///</summary>
        public string? firstName { get; set; }

        ///<summary>
        ///Whether the merchant has added timeline comments about the customer on the customer's page.
        ///</summary>
        [Obsolete("To query for comments on the timeline, use the `events` connection and a 'query' argument containing `verb:comment`, or look for a 'CommentEvent' in the `__typename` of `events`.")]
        [NonNull]
        public bool? hasTimelineComment { get; set; }

        ///<summary>
        ///A globally-unique ID.
        ///</summary>
        [NonNull]
        public string? id { get; set; }

        ///<summary>
        ///The image associated with the customer.
        ///</summary>
        [NonNull]
        public Image? image { get; set; }
        ///<summary>
        ///The customer's last name.
        ///</summary>
        public string? lastName { get; set; }
        ///<summary>
        ///The customer's last order.
        ///</summary>
        public Order? lastOrder { get; set; }

        ///<summary>
        ///The ID of the corresponding resource in the REST Admin API.
        ///</summary>
        [NonNull]
        public ulong? legacyResourceId { get; set; }

        ///<summary>
        ///The amount of time since the customer was first added to the store.
        ///
        ///Example: 'about 12 years'.
        ///</summary>
        [NonNull]
        public string? lifetimeDuration { get; set; }

        ///<summary>
        ///The customer's locale.
        ///</summary>
        [NonNull]
        public string? locale { get; set; }

        ///<summary>
        ///The market that includes the customer’s default address.
        ///</summary>
        [Obsolete("This `market` field will be removed in a future version of the API.")]
        public Market? market { get; set; }

        ///<summary>
        ///Whether the customer can be merged with another customer.
        ///</summary>
        [NonNull]
        public CustomerMergeable? mergeable { get; set; }
        ///<summary>
        ///A [custom field](https://shopify.dev/docs/apps/build/custom-data),
        ///including its `namespace` and `key`, that's associated with a Shopify resource
        ///for the purposes of adding and storing additional information.
        ///</summary>
        public Metafield? metafield { get; set; }

        ///<summary>
        ///List of metafield definitions.
        ///</summary>
        [Obsolete("This field will be removed in a future version. Use `QueryRoot.metafieldDefinitions` instead.")]
        [NonNull]
        public MetafieldDefinitionConnection? metafieldDefinitions { get; set; }

        ///<summary>
        ///A list of [custom fields](https://shopify.dev/docs/apps/build/custom-data)
        ///that a merchant associates with a Shopify resource.
        ///</summary>
        [NonNull]
        public MetafieldConnection? metafields { get; set; }
        ///<summary>
        ///A unique identifier for the customer that's used with Multipass login.
        ///</summary>
        public string? multipassIdentifier { get; set; }
        ///<summary>
        ///A note about the customer.
        ///</summary>
        public string? note { get; set; }

        ///<summary>
        ///The number of orders that the customer has made at the store in their lifetime.
        ///</summary>
        [NonNull]
        public ulong? numberOfOrders { get; set; }

        ///<summary>
        ///A list of the customer's orders.
        ///</summary>
        [NonNull]
        public OrderConnection? orders { get; set; }

        ///<summary>
        ///A list of the customer's payment methods.
        ///</summary>
        [NonNull]
        public CustomerPaymentMethodConnection? paymentMethods { get; set; }

        ///<summary>
        ///The customer's phone number.
        ///</summary>
        [Obsolete("Use `defaultPhoneNumber.phoneNumber` instead.")]
        public string? phone { get; set; }

        ///<summary>
        ///Possible subscriber states of a customer defined by their subscription contracts.
        ///</summary>
        [NonNull]
        public string? productSubscriberStatus { get; set; }

        ///<summary>
        ///The current SMS marketing state for the customer's phone number.
        ///
        ///If the customer does not have a phone number, then this property is `null`.
        ///</summary>
        [Obsolete("Use `defaultPhoneNumber.marketingState`, `defaultPhoneNumber.marketingOptInLevel`, `defaultPhoneNumber.marketingUpdatedAt`, `defaultPhoneNumber.marketingCollectedFrom`, and `defaultPhoneNumber.sourceLocation` instead.")]
        public CustomerSmsMarketingConsentState? smsMarketingConsent { get; set; }

        ///<summary>
        ///The state of the customer's account with the shop.
        ///
        ///Please note that this only meaningful when Classic Customer Accounts is active.
        ///</summary>
        [NonNull]
        public string? state { get; set; }

        ///<summary>
        ///The statistics for a given customer.
        ///</summary>
        [NonNull]
        public CustomerStatistics? statistics { get; set; }

        ///<summary>
        ///Returns a list of store credit accounts that belong to the owner resource.
        ///A store credit account owner can hold multiple accounts each with a different currency.
        ///</summary>
        [NonNull]
        public StoreCreditAccountConnection? storeCreditAccounts { get; set; }

        ///<summary>
        ///A list of the customer's subscription contracts.
        ///</summary>
        [NonNull]
        public SubscriptionContractConnection? subscriptionContracts { get; set; }

        ///<summary>
        ///A comma separated list of tags that have been added to the customer.
        ///</summary>
        [NonNull]
        public IEnumerable<string>? tags { get; set; }

        ///<summary>
        ///Whether the customer is exempt from being charged taxes on their orders.
        ///</summary>
        [NonNull]
        public bool? taxExempt { get; set; }

        ///<summary>
        ///The list of tax exemptions applied to the customer.
        ///</summary>
        [NonNull]
        public IEnumerable<string>? taxExemptions { get; set; }

        ///<summary>
        ///The URL to unsubscribe the customer from the mailing list.
        ///</summary>
        [Obsolete("Use `defaultEmailAddress.marketingUnsubscribeUrl` instead.")]
        [NonNull]
        public string? unsubscribeUrl { get; set; }

        ///<summary>
        ///The date and time when the customer was last updated.
        ///</summary>
        [NonNull]
        public DateTime? updatedAt { get; set; }

        ///<summary>
        ///Whether the email address is formatted correctly.
        ///
        ///Returns `true` when the email is formatted correctly and
        ///belongs to an existing domain. This doesn't guarantee that
        ///the email address actually exists.
        ///</summary>
        [Obsolete("Use `defaultEmailAddress.validFormat` instead.")]
        [NonNull]
        public bool? validEmailAddress { get; set; }

        ///<summary>
        ///Whether the customer has verified their email address. Defaults to `true` if the customer is created through the Shopify admin or API.
        ///</summary>
        [NonNull]
        public bool? verifiedEmail { get; set; }
    }

