    ///<summary>
    ///The different kinds of order transactions.
    ///</summary>
    public enum OrderTransactionKind
    {
        ///<summary>
        ///An authorization and capture performed together in a single step.
        ///</summary>
        SALE,
        ///<summary>
        ///A transfer of the money that was reserved by an authorization.
        ///</summary>
        CAPTURE,
        ///<summary>
        ///An amount reserved against the cardholder's funding source.
        ///Money does not change hands until the authorization is captured.
        ///</summary>
        AUTHORIZATION,
        ///<summary>
        ///A cancelation of an authorization transaction.
        ///</summary>
        VOID,
        ///<summary>
        ///A partial or full return of captured funds to the cardholder.
        ///A refund can happen only after a capture is processed.
        ///</summary>
        REFUND,
        ///<summary>
        ///The money returned to the customer when they've paid too much during a cash transaction.
        ///</summary>
        CHANGE,
        ///<summary>
        ///An authorization for a payment taken with an EMV credit card reader.
        ///</summary>
        EMV_AUTHORIZATION,
        ///<summary>
        ///A suggested refund transaction that can be used to create a refund.
        ///</summary>
        SUGGESTED_REFUND,
    }

    public static class OrderTransactionKindStringValues
    {
        public const string SALE = @"SALE";
        public const string CAPTURE = @"CAPTURE";
        public const string AUTHORIZATION = @"AUTHORIZATION";
        public const string VOID = @"VOID";
        public const string REFUND = @"REFUND";
        public const string CHANGE = @"CHANGE";
        public const string EMV_AUTHORIZATION = @"EMV_AUTHORIZATION";
        public const string SUGGESTED_REFUND = @"SUGGESTED_REFUND";
    }

    ///<summary>
    ///The different states that an `OrderTransaction` can have.
    ///</summary>
    public enum OrderTransactionStatus
    {
        ///<summary>
        ///The transaction succeeded.
        ///</summary>
        SUCCESS,
        ///<summary>
        ///The transaction failed.
        ///</summary>
        FAILURE,
        ///<summary>
        ///The transaction is pending.
        ///</summary>
        PENDING,
        ///<summary>
        ///There was an error while processing the transaction.
        ///</summary>
        ERROR,
        ///<summary>
        ///Awaiting a response.
        ///</summary>
        AWAITING_RESPONSE,
        ///<summary>
        ///The transaction status is unknown.
        ///</summary>
        UNKNOWN,
    }

    public static class OrderTransactionStatusStringValues
    {
        public const string SUCCESS = @"SUCCESS";
