    ///<summary>
    ///The payment schedule for a payments account.
    ///</summary>
    public class ShopifyPaymentsPayoutSchedule : GraphQLObject<ShopifyPaymentsPayoutSchedule>
    {
        ///<summary>
        ///The interval at which payouts are sent to the connected bank account.
