    ///A Shopify product taxonomy attribute.
    ///</summary>
    public class TaxonomyAttribute : GraphQLObject<TaxonomyAttribute>, INode, ITaxonomyCategoryAttribute
    {
        ///<summary>
        ///A globally-unique ID.
